local zs=ys.trust and not ys.trust.ok
xs.why=(xs.why or tlc[312])..tlc[1721]..(zs and string.format(ys.trust.ratio<0.1 and tlc[1722]or tlc[1723],ys.trust.ratio)or tostring(ys.playing or ys.margin))
