local Fs,Gs={},{}
for Hs,Is in ipairs(vs)do
if Is~=Es then
if N.dropsGoal(Is)or Is.train then
Is.why=tlc[1726]..(Is.why or tlc[312])
table.insert(Fs,Is)
else
table.insert(Gs,Is)
end
end
end
if#Fs>0 then
vs={}
if Es then
table.insert(vs,Es)
end
for Js,Ks in ipairs(Fs)do
table.insert(vs,Ks)
end
for Ls,Ms in ipairs(Gs)do
table.insert(vs,Ms)
end
end
end
for Ns,Os in ipairs(vs)do
if Os.kind==tlc[1535]then
local Ps=vs[1]
if Ns>1 and Ps.kind~=tlc[1534]and not(Ps.kind==tlc[1403]and Ps.started)then
table.remove(vs,Ns)
table.insert(vs,1,Os)
Os.why=tlc[1727]..(Os.why or tlc[312])
end
break
end
end
local Qs=vs[1]
if Qs and Qs.kind==tlc[1418]and Qs.first then
local Rs,Ss=Qs,(Qs.baseScore or Qs.score)*N.CHAIN_MIN
for Ts=1,6 do
local Us
for Vs,Ws in ipairs(vs)do
if Ws.kind==tlc[1418]and Ws.first and Ws.diff==Rs.diff and(Ws.baseScore or Ws.score)>=Ss and N.nextAct(Ws.level)==Rs.level then
Us=Ws
break
end
end
if not Us then
break
end
Rs=Us
end
if Rs~=Qs then
table.remove(vs,table.find(vs,Rs))
table.insert(vs,1,Rs)
Rs.why=tlc[1728]..(Rs.why or tlc[312])
end
end
if I.nextMode then
