function cb.relicWorth(iD,jD)
local kD=jD._unique_item_data and jD._unique_item_data._unique_relic_data
if not kD then
return 0
end
local lD=G.Items[jD.item_id]or{}
local mD,nD=M.types(iD.unit_id)
