return 0
end
local oD,pD=0,0
for qD,rD in pairs(kD._core_damage_type_buffs or{})do
if mD[rD.damage_type]then
oD=oD+(tonumber(rD.mul)or 0)+(tonumber(rD.add_upg)or 0)*0.01+(tonumber(rD.pen)or 0)*0.001
pD=pD+(tonumber(rD.crit)or 0)
end
