oD=oD+pD*0.5
local sD=M.rows(iD.unit_id)
local tD=sD and sD[sD.max]
local uD=(tD and tonumber(tD.cd)or 0)*M.mult(iD,tlc[1517])
for vD,wD in pairs(kD._unique_relic_effects or{})do
local xD=type(wD.params)==tlc[1383]and wD.params or{}
if wD.id==tlc[1850]then
local yD=math.min(1,(tonumber(xD.extra_damage)or 0)*uD/math.max(1,tonumber(xD.time_interval)or 40))
local zD=M.DRONES and M.DRONES[iD.unit_id]
if zD and zD.late and uD>0 then
local AD=1/uD
yD=yD*AD/(AD+(tonumber(zD.max)or 0)*(tonumber(zD.late.dmg)or 0)*(tonumber(zD.hits)or 1)/math.max(0.1,tonumber(zD.late.cd)or 4))
end
oD=oD+yD
elseif wD.id==tlc[1851]then
oD=oD+(tonumber(xD.dmg_buff)or 0)*0.25
elseif wD.id==tlc[1852]then
oD=oD+(tonumber(xD.dmg_buff)or 0)*pD
elseif wD.id==tlc[1853]then
if mD.magic then
oD=0
else
oD=oD+(tonumber(xD.dmg_buff)or 0)*0.3
end
elseif wD.id==tlc[1854]then
if mD.water_damage then
oD=oD+0.05
end
end
end
return oD
end
