function bb.pick(epb)
local fpb,gpb=bb.curses(epb),bb.lives(epb)
local hpb=bb.res(epb)
local ipb=bb.rooms(epb)
local jpb={}
for kpb,lpb in ipairs(ipb)do
table.insert(jpb,tostring(lpb.r._r))
end
