for ppb,qpb in ipairs(ipb)do
local rpb=bb.roomValue(qpb,hpb)
local spb,tpb
for upb,vpb in ipairs(bb.after(epb,qpb.choice))do
local wpb=bb.roomValue(vpb,hpb)
if not spb or wpb>spb then
spb,tpb=wpb,vpb
end
end
