local zpb=1-(1-xpb)^math.max(1,gpb)
local Apb=gpb>=3 and 1 or(gpb==2 and 2 or 6)
qpb.p,qpb.sim,qpb.value,qpb.nextValue,qpb.nextRoom=xpb,ypb,rpb,spb or 0,tpb
