if Bpb and not Cpb then
qpb.blocked=Dpb
end
if not qpb.blocked and(not npb or qpb.score>npb.score)then
npb=qpb
end
if not opb or qpb.score>opb.score then
opb=qpb
end
end
npb=npb or opb
bb._pick={sig=mpb,x=npb,rooms=ipb}
return npb
end
