function P.buildPath()
P.samples={}
local Hub=G.PATH and G.PATH.PATH_CACHE and G.PATH.PATH_CACHE[workspace._BASES.pve]
if not Hub then
return
end
for Iub,Jub in pairs(Hub)do
if not(G.PATH.HIDDEN_MOCK_LANES and G.PATH.HIDDEN_MOCK_LANES[Iub.Name])then
local Kub={}
for Lub,Mub in ipairs(Jub.points or{})do
table.insert(Kub,Mub.part.Position)
end
local Nub=0
for Oub=2,#Kub do
Nub=Nub+(Kub[Oub]-Kub[Oub-1]).Magnitude
end
local Pub=0
for Qub=2,#Kub do
local Rub,Sub=Kub[Qub-1],Kub[Qub]
local Tub=(Sub-Rub).Magnitude
local Uub=math.max(1,math.floor(Tub/2))
for Vub=0,Uub-1 do
local Wub=Rub:Lerp(Sub,Vub/Uub)
table.insert(P.samples,{pos=Wub,prog=(Pub+Tub*Vub/Uub)/math.max(1,Nub),lane=Iub.Name})
end
Pub=Pub+Tub
end
if Kub[#Kub]then
table.insert(P.samples,{pos=Kub[#Kub],prog=1,lane=Iub.Name})
end
end
end
local Xub,Yub,Zub={},0,0
for _ub,avb in ipairs(P.samples)do
local bvb=tostring(avb.lane)
if not Xub[bvb]then
Yub=Yub+1
end
Xub[bvb]=(Xub[bvb]or 0)+1
Zub=Zub+1
end
P.laneCount={n=Yub,by=Xub,avg=Yub>0 and Zub/Yub or 1}
end
