local NQb={}
for OQb,PQb in pairs(EQb)do
local QQb,RQb=1,{}
for SQb,TQb in pairs(type(PQb)==tlc[1383]and PQb.effects or{})do
if type(TQb)==tlc[1383]then
local UQb=P.rogueEffect(TQb)
QQb=QQb*UQb
table.insert(RQb,P.effectText(TQb))
end
end
if type(PQb)==tlc[1383]and PQb.weather then
QQb=QQb*db.weatherStrength(PQb.weather)/math.max(0.05,IQb)
end
local VQb=type(PQb)==tlc[1383]and db.cardGems(PQb,FQb)or 0
local WQb=QQb>=1 or(P.fhP*QQb>=GQb and not HQb)
local XQb=math.log(math.max(0.05,QQb))*db.STRENGTH_GEMS+(WQb and VQb or-1000)
if not KQb or XQb>KQb then
JQb,KQb,LQb,MQb=OQb,XQb,QQb,VQb
end
table.insert(NQb,string.format(tlc[2829],tostring(OQb),tostring(type(PQb)==tlc[1383]and PQb.title or tlc[1596]),(type(PQb)==tlc[1383]and PQb.weather)and(tlc[1668]..tostring(PQb.weather)..tlc[1669])or tlc[312],tostring(type(PQb)==tlc[1383]and PQb.option_type or tlc[1596]),QQb,math.floor(VQb+0.5),table.concat(RQb,tlc[2483])))
end
