function P.learn()
local rSb,sSb={},{}
local tSb,uSb=0,0
for vSb,wSb in ipairs(P.mine)do
local xSb=wSb._stats
local ySb=xSb.id.Value
local zSb=xSb:FindFirstChild(tlc[2735])and xSb.total_damage.Value or 0
if not M.isFarm(ySb)then
rSb[ySb]=(rSb[ySb]or 0)+zSb
sSb[ySb]=(sSb[ySb]or 0)+P.liveDps(wSb,ySb)/math.max(0.5,M.nudge(ySb))
local ASb=M.passive(ySb).mark
if ASb then
sSb[ySb]=sSb[ySb]+ASb.dot*xSb.damage.Value
end
tSb=tSb+zSb
end
end
for BSb,CSb in pairs(sSb)do
uSb=uSb+CSb
end
if tSb<=0 or uSb<=0 then
return
end
P.lastEff={}
for DSb,ESb in pairs(rSb)do
local FSb,GSb=ESb/tSb,sSb[DSb]/uSb
if GSb>0.02 then
local HSb=I.learn[DSb]or{eff=1,n=0}
local ISb=math.max(0.02,0.25*math.sqrt(30/(30+HSb.n)))
local JSb=L.clamp(FSb/GSb,0.3,3)
P.lastEff[DSb]=math.floor(JSb*1000+0.5)/1000
HSb.eff=HSb.eff+(JSb-HSb.eff)*ISb
HSb.n=HSb.n+1
I.learn[DSb]=HSb
end
end
end
